@extends('layouts.app') @section('title','Task List') @section('content')<h1>Task List</h1>@auth<a class="button" href="{{ route('tasks.create') }}">Create task</a>@else<p><a href="{{ route('login') }}">Log in</a> to create or manage tasks.</p>@endauth @forelse($tasks as $task)<article class="card"><h2>{{ $task->title }}</h2><p>{{ $task->description }}</p><p>Status: <strong>{{ str($task->status)->replace('_',' ')->title() }}</strong> · Due {{ $task->due_date->format('M j, Y') }}</p>@auth<a href="{{ route('tasks.edit',$task) }}">Edit</a><form method="POST" action="{{ route('tasks.destroy',$task) }}" onsubmit="return confirm('Archive this task?')">@csrf @method('DELETE')<button>Archive</button></form>@endauth</article>@empty<p>No active tasks yet.</p>@endforelse @endsection
